		candidateCtx, cancel := context.WithTimeout(ctx, fetchTimeout)
		target, authoritative := checkpointFetchTargetFrom(candidateCtx, remoteName)
		err := probeAndFetchCheckpointRef(candidateCtx, ref, target, authoritative)
		cancel()
